import { StringColumn, BooleanColumn } from '@servicenow/sdk/core'
import { action, Subflow, wfa } from '@servicenow/sdk/automation'

export const test_subflow_with_datapills = Subflow(
    {
        $id: Now.ID['da624de937e1be180e11a3e734924bda'],
        name: 'test_subflow_with_datapills',
        description: 'Subflow to create a incident and a a log message with incident number',
        runAs: 'user',
        inputs: {
            short_description: StringColumn({
                label: 'Short Description',
                maxLength: 8000,
            }),
            high_priority: BooleanColumn({
                label: 'High Priority',
                default: true,
            }),
        },
        outputs: {
            output1: BooleanColumn({
                label: 'Output1',
            }),
            output2: StringColumn({
                label: 'Output2',
                maxLength: 8000,
            }),
        },
        flowVariables: {
            flow_variable1: StringColumn({
                label: 'flow_variable1',
                maxLength: 8000,
            }),
        },
    },
    (params) => {
        const action_instance_1 = wfa.action(
            action.core.createRecord,
            {
                $id: Now.ID['efe241e53725be180e11a3e734924b8e'],
                annotation: 'create incident record',
                uuid: 'ae0c76d5-f5ee-432f-ae71-4aba0dcdf815',
            },
            {
                table_name: 'incident',
                values: `short_description=${wfa.dataPill(params.inputs.short_description, 'string')}`,
            }
        )
        wfa.subflow(
            'a055540f534e2010c232ddeeff7b12db',
            {
                $id: Now.ID['7c6409e137a5be180e11a3e734924bc5'],
                annotation: 'Add a pause of 10 secs',
                uuid: 'b947317d-3c72-4feb-9950-570d7b6ab3ec',
            },
            {
                seconds: wfa.dataPill(params.flowVariables.flow_variable1, 'string'),
            }
        )
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['abe241e53725be180e11a3e734924b90'],
                annotation: 'log the incident number',
                uuid: 'd8389194-5f52-48ee-82a5-8d052eb6c0a9',
            },
            {
                log_level: 'info',
                log_message: `Incident number : ${wfa.dataPill(action_instance_1.table_name, 'string')}`,
            }
        )
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['c8a301653765be180e11a3e734924b17'],
                annotation: 'Log incident',
                uuid: '83842bf1-a48b-498d-8506-81ef739c1e83',
            },
            {
                log_level: 'info',
                log_message: wfa.dataPill(action_instance_1.type, 'string'),
            }
        )
    }
)
